mapper.update:
UPDATE tb_item SET name=#{name}, total_count=#{totalCount},
                   available_count=#{availableCount}, location=#{location}
WHERE item_id=#{itemId}

UPDATE tb_borrow_record
SET status = #{status}, return_time = NOW()
WHERE record_id = #{recordId}

mapper.select:
SELECT r.*, s.name as studentName, i.name as itemName, s.student_no as studentNo, s.class_name as className FROM tb_borrow_record r LEFT JOIN tb_student s ON r.student_id = s.student_id LEFT JOIN tb_item i ON r.item_id = i.item_id
AND r.student_id = #{studentId}
ORDER BY r.status ASC, r.borrow_time DESC
